/* Historical replay engine: all temporal rules are independent of presentation. */
(function(root){
const key=m=>[m.date,m.home,m.away].join('|');
function completed(m,date,closed,watched){return m.date<date||(m.date===date&&(closed.includes(date)||watched.includes(key(m))))}
function winPoints(league,season){league=league.split('-')[0];if(league==='england')return season>=1981?3:2;if(league==='spain'||league==='germany')return season>=1995?3:2;if(league==='italy')return season>=1994?3:2;if(league==='france')return season>=1994||season===1988?3:2;if(['holland','portugal','belgium'].includes(league))return season>=1995?3:2;if(league==='scotland')return season>=1994?3:2;if(league==='greece')return season>=1992?3:2;if(league==='turkey')return season>=1987?3:2;return 3}
function table(matches,options={}){const {date='9999',closed=[],watched=[],league='',season=2026,points=winPoints(league,season),live=[]}=options;const teams={};for(const m of matches){for(const n of [m.home,m.away])teams[n]??={name:n,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0,form:[]}}
let used=matches.filter(m=>completed(m,date,closed,watched));if(live.length){const ids=new Set(live.map(key));used=used.filter(m=>!ids.has(key(m))).concat(live)}for(const m of used){if(!teams[m.home]||!teams[m.away])continue;let a=teams[m.home],b=teams[m.away];a.p++;b.p++;a.gf+=m.hg;a.ga+=m.ag;b.gf+=m.ag;b.ga+=m.hg;if(m.hg>m.ag){a.w++;b.l++;a.pts+=points;a.form.push('W');b.form.push('L')}else if(m.hg<m.ag){b.w++;a.l++;b.pts+=points;a.form.push('L');b.form.push('W')}else{a.d++;b.d++;a.pts++;b.pts++;a.form.push('D');b.form.push('D')}}
const ratio=league==='england'&&season<1976;return Object.values(teams).map(t=>({...t,gd:t.gf-t.ga,ratio:t.ga?t.gf/t.ga:(t.gf?Infinity:0)})).sort((a,b)=>b.pts-a.pts||(ratio?b.ratio-a.ratio:b.gd-a.gd)||b.gf-a.gf||a.name.localeCompare(b.name))}
function minute(s){let a=String(s).split('+').map(Number);return (a[0]||0)+(a[1]||0)*.01}
function scoreAt(m,at){const g=(m.goals||[]).filter(g=>minute(g.minute)<=at);return [g.filter(g=>g.team===m.home).length,g.filter(g=>g.team===m.away).length]}
function canName(m,matches,date,closed,watched){if(m.date<=date)return true;if(m.group||/group|league|matchday|round 1|prelim/i.test(m.stage||''))return true;const stages=[...new Set(matches.filter(x=>!x.group).map(x=>x.stage))];let i=stages.indexOf(m.stage);if(i<0)return false;if(i===0){const gs=matches.filter(x=>x.group);return !gs.length||gs.every(x=>completed(x,date,closed,watched))}const prev=matches.filter(x=>x.stage===stages[i-1]);return prev.length>0&&prev.every(x=>completed(x,date,closed,watched))}
const api={key,completed,winPoints,table,minute,scoreAt,canName};root.ReplayEngine=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
